"""Build a searchable clause index and distinguish rules from implementation choices."""
import json
import re
from pathlib import Path

ROOT=Path(__file__).resolve().parent.parent/'references/norm-source'


def build():
    source=json.loads((ROOT/'source.json').read_text(encoding='utf-8'))
    clauses=[]
    for page in source['pages']:
        text=page['text']
        matches=list(re.finditer(r'(?m)^\s*(\d{1,2}(?:\.\d+){1,3})(?=[\s.])',text))
        for i,match in enumerate(matches):
            end=matches[i+1].start() if i+1<len(matches) else len(text)
            clauses.append({'clause':match[1],'page':page['page'],'text':text[match.start():end].strip(),
                            'note':'Индекс вхождений; включает оглавление и примеры, не заменяет чтение контекста страницы.'})
    (ROOT/'clauses.json').write_text(json.dumps(clauses,ensure_ascii=False,indent=2),encoding='utf-8')
    rules=[
        ('6.1','Обязательны титул, введение, основная часть, заключение и источники. Исключение для лабораторных в этом пункте не сформулировано.','mandatory'),
        ('6.2','Учебный шифр не включает учётный номер ВКР; для ВКР предусмотрены учётный номер и год.','mandatory'),
        ('6.2д','Гриф допуска отмечен обязательным с оговоркой о выпускающих кафедрах и курсовых работах; нельзя придумывать подписанта.','conditional'),
        ('6.4','Содержание можно не составлять только при объёме не более десяти страниц.','mandatory'),
        ('6.4','Содержание располагается симметрично тексту; перечисляет реальные заголовки и страницы.','mandatory'),
        ('6.7','Введение раскрывает состояние проблемы, основания, исходные данные, актуальность и новизну.','content-review'),
        ('6.9','Заключение содержит выводы, оценку полноты решения задач, рекомендации и оценку результатов.','content-review'),
        ('6.10','Название: Список использованных источников либо Библиографический список; описание по указанному в PDF ГОСТ 7.1-2003.','mandatory'),
        ('7.1.1','А4; для перечисленных графических материалов допускается А3.','mandatory'),
        ('7.1.2','Рамка и основная надпись кроме титула, толщина рамки 0,75 пт; формы приложения И.','mandatory'),
        ('7.1.3','Учебный текст Times New Roman чёрный 14 пт, в таблицах допускается 12 пт, интервал 1,5.','mandatory'),
        ('7.1.3','Курсив разрешён для выделения терминов, формул, теорем; не является запретом любого курсива.','permission'),
        ('7.1.4','Отступ текста от рамки не менее 3–5 мм; абзац 10 мм.','mandatory'),
        ('7.1.5','До 100 листов с приложениями — требование для ВКР, не общий предел курсовой.','conditional'),
        ('7.2.2','Арабские номера без завершающей точки; подразделы внутри своего раздела.','mandatory'),
        ('7.2.7','Перечисления с дефисом, буквами со скобкой при ссылках; дальнейшая детализация цифрами со скобкой.','mandatory'),
        ('7.2.9','Заголовки можно центрировать либо начинать с абзацного отступа.','permission'),
        ('7.2.10','Раздел начинается с нового листа; требование не распространено здесь на каждый подраздел.','mandatory'),
        ('7.2.11','Нумерация сквозная, титул учитывается без печатного номера; номер в правой позиции основной надписи.','mandatory'),
        ('7.3.1–7.3.11','Точность терминов, отсутствие разговорности, правила чисел, единиц, знаков и сокращений.','content-review'),
        ('7.4','Правила формул, пояснений и ссылок применяются при наличии формул.','conditional'),
        ('7.5','Нумерация рисунков, текстовые ссылки; название при необходимости, подрисуночный текст под иллюстрацией.','conditional'),
        ('7.6.5','Высота строк не менее 8 мм; диагональное деление заголовков не допускается.','conditional'),
        ('7.6.7','Разделение большой таблицы на части разрешено с повторением головки/боковика; программная подготовка допускает не указывать Продолжение таблицы.','permission'),
        ('7.7–7.10','Сноски, примечания, примеры и приложения проверяются при наличии соответствующих объектов.','conditional'),
        ('8','Дополнительные правила самостоятельных графических документов; нельзя механически применять ко всему тексту.','conditional'),
        ('9','Выбор группировки источников и описания разных видов изданий.','content-review'),
        ('Приложение Б','Компоновка титульника показана образцами. Ось по центру листа и точные интервалы в пунктах не заданы.','example'),
        ('Приложения Г, К','Таблицы со скрытой сеткой рекомендуются; исключительный запрет TOC или точки после номера не сформулирован.','recommendation'),
        ('Приложение Д','Образцы перечислений: строчные начала, точка с запятой, завершающая точка, вложенность; развёрнутые позиции допускают курсивное выделение в начале абзаца.','example'),
        ('Приложение Е','Заголовок с прописной, без завершающей точки/подчёркивания/переносов; расстояние до текста — два интервала. Число 28 пт буквально не указано.','mandatory'),
        ('Приложение И','И.3: заглавный лист текстового документа 185×40 мм; И.4: последующие 185×15 мм. Геометрия проверена по рисункам на странице 44 один раз.','figure-transcription'),
        ('Приложение И','В текстовом слое PDF не заданы числовые кегли 16/9 и имя ISOCPEUR для шифра. Технические значения не выдаются за обязательные нормы.','not-specified')]
    data={'source_sha256':source['sha256'],'precedence':'PDF > этот реестр > технические параметры; прежние пользовательские предпочтения не отменяют PDF.',
          'rules':[{'source':a,'requirement':b,'status':c} for a,b,c in rules],
          'implementation_choices':{'heading_gap':'Один добавочный шаг строк, измеренный через Wordcraft; суммарно два шага до текста. Число пунктов не задано PDF.','stamp_code_size':16,'stamp_size':9,
             'note':'Числа не утверждаются как буквально заданные PDF. Геометрия и вёрстка требуют проверки; при противоречии приоритет у PDF.'}}
    (ROOT/'requirements.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
    (ROOT/'README.md').write_text('# Машиночитаемый источник нормоконтроля\n\n'+
        'Полный текст: [full-text.md](full-text.md). Полная геометрия и текстовые блоки: [source.json](source.json).\n\n'+
        'Индекс пунктов: [clauses.json](clauses.json). Проверенный реестр: [requirements.json](requirements.json).\n\n'+
        'Исходные изображения и их координаты: [assets.json](assets.json), каталоги images и vectors. Растровые полосы — оригиналы из PDF, а не скриншоты. OCR не выполнялся; отсутствие надписи в текстовом слое не доказывает её отсутствия в рисунке.\n\n'+
        'Геометрия И.3 и И.4 сверена с рисунком на странице 44. Текст нельзя использовать для выдумывания отсутствующих кеглей.\n',encoding='utf-8')


if __name__=='__main__':build()
